actions.script:
if (!enumeration) {
    ec.web.sendJsonResponse({ title: recordId, typeLabel: recordEntity, id: recordId })
} else {
    const type = ec.entity.find('moqui.basic.EnumerationType').condition('enumTypeId', enumeration.enumTypeId).one()
    ec.web.sendJsonResponse({ title: enumeration.description || enumeration.enumId, typeLabel: 'Enumeration', icon: 'sym_o_label',
        id: enumeration.enumId, url: '/qapps/gallery/Detail?enumId=' + encodeURIComponent(enumeration.enumId),
        status: { label: 'Active', color: 'positive' },
        fields: [{ label: 'Type', value: type?.description || enumeration.enumTypeId }, { label: 'Sequence', value: enumeration.sequenceNum ?? '' }] })
}

render-mode.text:
${JSON.stringify((() => {
                    const enumeration = recordId ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', recordId).one() : null
                    if (!enumeration) return {t: 'text', id: 'ChatterRecord', style: 'strong', text: ((recordEntity || '') + ' ' + (recordId || '')).trim() || 'No record'}
                    const type = ec.entity.find('moqui.basic.EnumerationType').condition('enumTypeId', enumeration.enumTypeId).one()
                    return {t: 'box', id: 'ChatterRecord', title: 'Enumeration ' + enumeration.enumId, c: [
                        {t: 'link', id: 'ChatterRecordLink', kind: 'anchor', text: enumeration.description || enumeration.enumId,
                            url: sri.buildUrl('../Detail').url + '?enumId=' + encodeURIComponent(enumeration.enumId)},
                        {t: 'text', id: 'ChatterRecordFields', text: 'Active · Type: ' + ((type && type.description) || enumeration.enumTypeId) +
                            (enumeration.sequenceNum == null ? '' : ' · Sequence: ' + enumeration.sequenceNum)}]}
                })())}

{"t": "component", "id": "ChatterTimeline", "name": "timeline", "props": {"items": [
    {"time": "Today 09:12", "title": "John Doe logged a note", "text": "Description reviewed with @John Doe and the Products team.", "kind": "primary"},
    {"time": "Yesterday 16:40", "title": "Ada Lovelace logged a call", "kind": "primary"},
    {"time": "Last week", "title": "spec-sheet.pdf was attached", "kind": "secondary"}
]}}
